import type { Exercise } from '../engine/types';

// Lot « cryptography » — exercices experts générés (multi-agent), ancrés sur des
// sources de référence. Options équilibrées, bonne réponse en index 0
// (position randomisée par shuffle.ts).
export const cryptographyExercises: Exercise[] = [
  {"id":"cr-propriete-d-une-fonction-de-hachage","type":"mcq","domain":"software","topic":"cryptography","difficulty":"junior","title":"Propriété d'une fonction de hachage","company":"Aumasson « Serious Cryptography », chap. 6 (Hash Functions)","question":"Quelle propriété fondamentale une fonction de hachage cryptographique doit-elle garantir ?","options":["Retrouver une entrée depuis son empreinte est infaisable (préimage)","Elle chiffre les données de façon réversible avec une clé secrète","Elle compresse les données pour réduire leur taille de stockage","Elle produit une empreinte de longueur variable selon l'entrée"],"answer":0,"explanation":"Une fonction de hachage cryptographique est déterministe, produit une empreinte de longueur FIXE, et doit résister à trois attaques : préimage (retrouver l'entrée depuis l'empreinte), seconde préimage, et collision. Ce n'est PAS du chiffrement : il n'y a pas de clé et l'opération est à sens unique, donc non réversible. Elle ne sert pas à compresser pour du stockage récupérable.","tags":["hachage","préimage","sha-2","intégrité","propriétés"],"optionNotes":["Exact : le hachage est à sens unique, retrouver l'entrée depuis l'empreinte doit être infaisable.","Non : le hachage n'a pas de clé et est irréversible ; ceci décrit le chiffrement symétrique.","Non : le but est l'intégrité, pas la compression ; on ne récupère jamais les données d'origine.","Faux : l'empreinte est de longueur FIXE (ex. 256 bits) quelle que soit la taille de l'entrée."]},
  {"id":"cr-role-du-sel","type":"mcq","domain":"software","topic":"cryptography","difficulty":"junior","title":"Rôle du sel","company":"Ferguson/Schneier/Kohno « Cryptography Engineering » ; OWASP Password Storage","question":"À quoi sert un sel (salt) lors du hachage d'un mot de passe ?","options":["Empêcher les tables arc-en-ciel et distinguer deux mots de passe identiques","Chiffrer le mot de passe afin de pouvoir le déchiffrer au login","Accélérer le calcul de l'empreinte pour améliorer les performances","Compresser l'empreinte pour économiser de l'espace en base de données"],"answer":0,"explanation":"Le sel est une valeur aléatoire unique par utilisateur, ajoutée avant le hachage. Il garantit que deux personnes avec le même mot de passe ont des empreintes différentes et rend inutilisables les tables arc-en-ciel (précalculées). Le hachage reste à sens unique : le sel n'a rien à voir avec du chiffrement réversible et n'accélère rien.","tags":["mot-de-passe","sel","rainbow-table","hachage","stockage"],"optionNotes":["Exact : un sel aléatoire unique casse les tables arc-en-ciel et disjoint deux mots de passe égaux.","Non : le sel ne chiffre rien ; le hachage reste à sens unique, on ne déchiffre jamais.","Faux : le sel n'accélère pas ; on veut au contraire un hachage lent (bcrypt, Argon2).","Non : le sel ne compresse pas ; il ajoute même de l'aléa stocké à côté de l'empreinte."]},
  {"id":"cr-chiffrement-symetrique","type":"mcq","domain":"software","topic":"cryptography","difficulty":"junior","title":"Chiffrement symétrique","company":"Wong « Real-World Cryptography », chap. 4","question":"Qu'est-ce qui caractérise le chiffrement symétrique ?","options":["La même clé secrète sert à chiffrer et à déchiffrer les données","Une clé publique chiffre et une clé privée déchiffre les données","Aucune clé n'est nécessaire, seul un algorithme public suffit","La clé de déchiffrement se calcule facilement depuis le texte chiffré"],"answer":0,"explanation":"En symétrique (AES, ChaCha20), une seule clé partagée sert au chiffrement et au déchiffrement. Le cas clé publique/privée décrit l'asymétrique. Le principe de Kerckhoffs impose que l'algorithme soit public et que TOUTE la sécurité repose sur le secret de la clé ; un chiffrement dont la clé se déduit du chiffré serait cassé.","tags":["symétrique","aes","clé-secrète","chiffrement"],"optionNotes":["Exact : en symétrique (AES, ChaCha20) une seule clé partagée chiffre et déchiffre.","Non : clé publique/privée décrit l'asymétrique (RSA, ECC), pas le symétrique.","Faux : Kerckhoffs impose l'algo public MAIS une clé secrète reste indispensable.","Non : un chiffrement dont la clé se déduit du chiffré serait tout simplement cassé."]},
  {"id":"cr-qu-est-ce-qu-aes","type":"mcq","domain":"software","topic":"cryptography","difficulty":"junior","title":"Qu'est-ce qu'AES","company":"Aumasson « Serious Cryptography », chap. 4 (Block Ciphers)","question":"Que désigne AES en cryptographie ?","options":["Un algorithme de chiffrement symétrique par blocs de 128 bits","Un algorithme asymétrique fondé sur les courbes elliptiques","Une fonction de hachage produisant une empreinte de 256 bits","Un protocole d'échange de clés dérivé de Diffie-Hellman"],"answer":0,"explanation":"AES (Rijndael) est un chiffrement symétrique par BLOCS de 128 bits, avec des clés de 128, 192 ou 256 bits. Ce n'est ni de l'asymétrique (ECC/RSA), ni du hachage (SHA), ni un protocole d'échange de clés (DH). Un chiffrement par blocs a besoin d'un MODE d'opération (CBC, CTR, GCM…) pour traiter des messages plus longs qu'un bloc.","tags":["aes","bloc","symétrique","rijndael","128-bits"],"optionNotes":["Exact : AES (Rijndael) chiffre par blocs de 128 bits, clés de 128/192/256 bits.","Non : l'asymétrique sur courbes elliptiques, c'est l'ECC ; AES est symétrique.","Faux : une empreinte de 256 bits évoque SHA-256, une fonction de hachage.","Non : l'échange de clés dérivé de DH n'est pas AES ; AES chiffre des données."]},
  {"id":"cr-cles-publique-et-privee","type":"mcq","domain":"software","topic":"cryptography","difficulty":"junior","title":"Clés publique et privée","company":"Wong « Real-World Cryptography », chap. 6","question":"Dans un système asymétrique, quel est le rôle des deux clés ?","options":["La clé publique se partage librement, la clé privée reste secrète","Les deux clés doivent rester secrètes entre les correspondants","La clé privée se partage, seule la clé publique reste secrète","Les deux clés sont publiques et l'algorithme reste secret"],"answer":0,"explanation":"En cryptographie asymétrique, chaque partie possède une paire : la clé publique se diffuse largement (pour chiffrer vers vous ou vérifier vos signatures), la clé privée reste strictement secrète (pour déchiffrer ou signer). Confondre les deux, ou garder l'algorithme secret, contredit le principe de Kerckhoffs.","tags":["asymétrique","clé-publique","clé-privée","rsa"],"optionNotes":["Exact : la clé publique se diffuse, la clé privée reste strictement secrète.","Non : garder les deux secrètes ressemble au symétrique, pas à l'asymétrique.","Faux : c'est l'inverse ; on ne partage jamais la clé privée.","Non : rendre l'algo secret viole Kerckhoffs ; la clé privée doit rester privée."]},
  {"id":"cr-apport-d-une-signature-numerique","type":"mcq","domain":"software","topic":"cryptography","difficulty":"junior","title":"Apport d'une signature numérique","company":"Ferguson/Schneier/Kohno « Cryptography Engineering » (signatures)","question":"Qu'apporte une signature numérique à un message ?","options":["L'authenticité et l'intégrité, vérifiables avec la clé publique du signataire","La confidentialité du message, illisible sans la clé privée","La compression du message pour accélérer sa transmission","La garantie que le message sera bien livré à son destinataire"],"answer":0,"explanation":"Une signature numérique prouve l'authenticité (qui a signé), l'intégrité (le message n'a pas été modifié) et offre la non-répudiation. On signe avec la clé PRIVÉE et on vérifie avec la clé PUBLIQUE. Elle n'assure PAS la confidentialité (c'est le rôle du chiffrement) ni la livraison réseau.","tags":["signature","authenticité","intégrité","non-répudiation"],"optionNotes":["Exact : on signe avec la clé privée, on vérifie avec la publique ; authenticité + intégrité.","Non : la confidentialité vient du chiffrement, pas de la signature (le message reste lisible).","Faux : une signature n'a rien à voir avec la compression du message.","Non : la signature ne garantit pas la livraison réseau, seulement l'origine et l'intégrité."]},
  {"id":"cr-contenu-d-un-certificat-x-509","type":"mcq","domain":"software","topic":"cryptography","difficulty":"junior","title":"Contenu d'un certificat X.509","company":"Wong « Real-World Cryptography », chap. 9 (PKI)","question":"Que contient essentiellement un certificat numérique X.509 ?","options":["Une clé publique liée à une identité, le tout signé par une autorité","La clé privée du serveur chiffrée avec un mot de passe fort","Le mot de passe de l'utilisateur haché avec un sel unique","La liste des algorithmes symétriques supportés par le serveur"],"answer":0,"explanation":"Un certificat X.509 lie une identité (nom de domaine, organisation) à une clé PUBLIQUE, avec une signature d'une autorité de certification (CA) qui atteste ce lien. La clé privée n'y figure JAMAIS : elle reste secrète côté serveur. C'est cette signature de la CA qui permet à un tiers de faire confiance à la clé publique.","tags":["certificat","x509","pki","clé-publique","autorité"],"optionNotes":["Exact : X.509 lie une identité à une clé publique, avec la signature d'une CA.","Non : la clé privée n'est JAMAIS dans le certificat ; elle reste secrète côté serveur.","Faux : un certificat ne contient aucun mot de passe utilisateur.","Non : la négociation des algos se fait dans le handshake TLS, pas dans le certificat."]},
  {"id":"cr-definition-d-un-csprng","type":"mcq","domain":"software","topic":"cryptography","difficulty":"junior","title":"Définition d'un CSPRNG","company":"Aumasson « Serious Cryptography », chap. 2 (Randomness)","question":"Qu'est-ce qu'un CSPRNG (générateur pseudo-aléatoire cryptographique) ?","options":["Un générateur dont on ne peut prédire les sorties futures ni passées","Un générateur rapide dont la graine est toujours l'heure système","Un générateur qui produit une suite reproductible pour les tests","Un générateur matériel qui n'a jamais besoin d'être ré-ensemencé"],"answer":0,"explanation":"Un CSPRNG produit des sorties indistinguables de l'aléa vrai : même en connaissant une partie de la suite, un attaquant ne peut prédire les valeurs suivantes ni remonter aux précédentes. Un PRNG classique (rand(), Math.random) est prévisible s'il est ensemencé sur l'heure et convient aux simulations, pas à la sécurité.","tags":["csprng","aléa","prng","imprévisibilité"],"optionNotes":["Exact : un CSPRNG rend les sorties imprévisibles, en avant comme en arrière.","Non : une graine sur l'heure système est justement prévisible et non sûre.","Faux : une suite reproductible convient aux tests, pas à la sécurité.","Non : même un TRNG matériel doit être correctement ensemencé et entretenu."]},
  {"id":"cr-role-de-hmac","type":"mcq","domain":"software","topic":"cryptography","difficulty":"junior","title":"Rôle de HMAC","company":"Aumasson « Serious Cryptography », chap. 7 (Keyed Hashing)","question":"À quoi sert un HMAC ?","options":["Vérifier l'intégrité et l'authenticité d'un message à l'aide d'une clé","Chiffrer un message avec une clé symétrique partagée","Générer une paire de clés publique et privée pour signer","Compresser un message avant de l'envoyer sur le réseau"],"answer":0,"explanation":"HMAC (Hash-based MAC) combine une fonction de hachage et une clé secrète pour produire un code d'authentification. Il prouve que le message n'a pas été altéré ET provient de quelqu'un connaissant la clé. Il ne chiffre pas (le message reste lisible) et ne génère pas de clés asymétriques.","tags":["hmac","intégrité","authenticité","mac","clé"],"optionNotes":["Exact : HMAC combine hachage et clé pour prouver intégrité et authenticité.","Non : HMAC ne chiffre pas ; le message reste lisible, seul un tag est ajouté.","Faux : HMAC est symétrique (une clé), il ne génère pas de paire de clés.","Non : HMAC ne compresse rien ; il produit un code d'authentification."]},
  {"id":"cr-danger-du-mode-ecb","type":"mcq","domain":"software","topic":"cryptography","difficulty":"junior","title":"Danger du mode ECB","company":"Aumasson « Serious Cryptography », chap. 4 (modes)","question":"Pourquoi le mode de chiffrement ECB est-il déconseillé ?","options":["Des blocs de clair identiques produisent des blocs chiffrés identiques","Il nécessite un vecteur d'initialisation trop long à générer","Il est beaucoup plus lent que les autres modes de chiffrement","Il ne fonctionne qu'avec des clés de 56 bits jugées faibles"],"answer":0,"explanation":"En ECB, chaque bloc est chiffré indépendamment avec la même clé : deux blocs de clair identiques donnent le MÊME chiffré. Les motifs des données transparaissent (célèbre image du « pingouin ECB » encore reconnaissable une fois chiffrée). ECB n'utilise même pas d'IV, ce qui aggrave le problème. Il faut lui préférer CTR, CBC ou mieux GCM.","tags":["ecb","mode","aes","motif","pingouin"],"optionNotes":["Exact : en ECB, blocs de clair identiques donnent des chiffrés identiques (le pingouin).","Faux : ECB n'utilise même pas d'IV, ce qui aggrave le problème.","Non : ECB n'est pas plus lent ; son défaut est la fuite de motifs.","Faux : les 56 bits évoquent DES ; ECB marche avec toute clé AES."]},
  {"id":"cr-role-de-l-iv-et-du-nonce","type":"mcq","domain":"software","topic":"cryptography","difficulty":"junior","title":"Rôle de l'IV et du nonce","company":"Wong « Real-World Cryptography », chap. 4","question":"Quel est le rôle d'un IV (vecteur d'initialisation) ou d'un nonce ?","options":["Rendre différents deux chiffrements du même clair avec la même clé","Servir de clé secrète supplémentaire pour renforcer le chiffrement","Authentifier le destinataire avant de lui envoyer le message","Remplacer le sel lors du hachage des mots de passe stockés"],"answer":0,"explanation":"L'IV/nonce introduit de la variabilité : avec la même clé, chiffrer deux fois le même message donne deux chiffrés différents, ce qui empêche un attaquant de détecter les répétitions. Il n'est PAS secret (il est souvent transmis en clair) mais doit respecter des contraintes d'unicité ou d'imprévisibilité selon le mode.","tags":["iv","nonce","mode","cbc","ctr"],"optionNotes":["Exact : l'IV/nonce varie chaque chiffrement, empêchant de détecter les répétitions.","Non : l'IV n'est pas secret et n'est pas une clé ; il est souvent transmis en clair.","Faux : l'IV n'authentifie personne ; l'authentification vient d'un MAC/AEAD.","Non : le sel sert au hachage de mots de passe, l'IV sert au chiffrement."]},
  {"id":"cr-garantie-de-l-aead","type":"mcq","domain":"software","topic":"cryptography","difficulty":"junior","title":"Garantie de l'AEAD","company":"Aumasson « Serious Cryptography », chap. 8 (Authenticated Encryption)","question":"Que garantit un chiffrement authentifié (AEAD) ?","options":["La confidentialité et l'intégrité/authenticité en une seule opération","Uniquement la confidentialité des données, sans contrôle d'intégrité","Uniquement l'intégrité des données, qui restent lisibles en clair","La compression des données avant de les chiffrer avec une clé"],"answer":0,"explanation":"L'AEAD (AES-GCM, ChaCha20-Poly1305) fournit à la fois la confidentialité (chiffrement) ET l'authenticité/intégrité (un tag détecte toute altération). Le « AD » (Associated Data) permet d'authentifier des en-têtes laissés en clair. C'est la primitive à privilégier plutôt que de combiner soi-même chiffrement et MAC.","tags":["aead","gcm","confidentialité","intégrité","chiffrement-authentifié"],"optionNotes":["Exact : l'AEAD (AES-GCM) offre confidentialité ET authenticité en une opération.","Non : la confidentialité seule, c'est du chiffrement simple, pas de l'AEAD.","Faux : l'AEAD chiffre aussi ; les données ne restent pas en clair.","Non : l'AEAD ne compresse pas ; le AD authentifie des en-têtes laissés en clair."]},
  {"id":"cr-resistance-aux-collisions","type":"mcq","domain":"software","topic":"cryptography","difficulty":"junior","title":"Résistance aux collisions","company":"Aumasson « Serious Cryptography », chap. 6","question":"Que signifie la résistance aux collisions d'une fonction de hachage ?","options":["Il est infaisable de trouver deux entrées ayant la même empreinte","Il est impossible que deux entrées aient la même empreinte","Chaque entrée produit une empreinte de longueur différente","L'empreinte peut toujours être inversée pour retrouver l'entrée"],"answer":0,"explanation":"Des collisions EXISTENT forcément (infinité d'entrées, empreintes de taille finie : principe des tiroirs). La résistance signifie qu'en trouver une est calculatoirement INFAISABLE, pas impossible. À cause du paradoxe des anniversaires, la sécurité contre les collisions n'est que de n/2 bits (128 bits pour SHA-256).","tags":["collision","hachage","anniversaire","sha-2","résistance"],"optionNotes":["Exact : les collisions existent (tiroirs) mais doivent être infaisables à trouver.","Faux : des collisions existent forcément ; « impossible » est trop fort.","Non : l'empreinte est de taille fixe, pas variable selon l'entrée.","Faux : le hachage est à sens unique ; on n'inverse jamais l'empreinte."]},
  {"id":"cr-but-de-diffie-hellman","type":"mcq","domain":"software","topic":"cryptography","difficulty":"junior","title":"But de Diffie-Hellman","company":"Wong « Real-World Cryptography », chap. 5 (Key Exchange)","question":"À quoi sert le protocole Diffie-Hellman ?","options":["Établir un secret partagé sur un canal non sûr, sans jamais l'échanger","Chiffrer directement de gros volumes de données de façon rapide","Signer un document pour prouver l'identité de son auteur","Hacher un mot de passe avec un facteur de coût élevé"],"answer":0,"explanation":"Diffie-Hellman permet à deux parties de calculer un secret commun en échangeant seulement des valeurs publiques : le secret lui-même ne transite jamais. Il n'authentifie pas (vulnérable à l'homme du milieu s'il est utilisé seul) et ne chiffre pas les données ; le secret obtenu sert ensuite à dériver des clés symétriques.","tags":["diffie-hellman","échange-clés","secret-partagé","dh"],"optionNotes":["Exact : DH calcule un secret commun sans jamais le faire transiter sur le canal.","Non : DH n'est pas un chiffrement de données ; il dérive ensuite des clés symétriques.","Faux : signer relève de RSA/ECDSA ; DH n'authentifie pas (risque MITM seul).","Non : hacher un mot de passe relève de bcrypt/Argon2, pas de DH."]},
  {"id":"cr-ne-pas-inventer-sa-crypto","type":"mcq","domain":"software","topic":"cryptography","difficulty":"junior","title":"Ne pas inventer sa crypto","company":"Ferguson/Schneier/Kohno « Cryptography Engineering »","question":"Pourquoi conseille-t-on de « ne jamais inventer sa propre cryptographie » ?","options":["Les primitives éprouvées ont été analysées longuement par des experts","Les algorithmes maison sont toujours plus lents à l'exécution","La loi interdit d'implémenter soi-même un algorithme de chiffrement","Les algorithmes standards sont gratuits alors que les autres non"],"answer":0,"explanation":"La solidité d'un algorithme ne vient pas de son secret mais de la cryptanalyse publique menée pendant des années par la communauté. Un schéma « maison » n'a subi aucun de ces tests et cache presque toujours une faille invisible à son auteur. La règle s'étend aussi aux implémentations : mieux vaut réutiliser des bibliothèques auditées.","tags":["bonnes-pratiques","primitives","standards","erreurs"],"optionNotes":["Exact : la solidité vient d'années de cryptanalyse publique, pas du secret de l'algo.","Non : la lenteur n'est pas le vrai risque ; c'est la faille cachée non détectée.","Faux : rien n'interdit légalement d'écrire un algo ; c'est juste dangereux.","Non : le coût n'est pas le sujet ; les standards sont d'ailleurs libres et gratuits."]},
  {"id":"cr-bcrypt-plutot-que-sha-256","type":"mcq","domain":"software","topic":"cryptography","difficulty":"intermediate","title":"bcrypt plutôt que SHA-256","company":"Aumasson « Serious Cryptography », chap. 7 ; OWASP Password Storage","question":"Pourquoi bcrypt est-il préférable à un simple SHA-256 pour stocker des mots de passe ?","options":["Il est délibérément lent et paramétrable, ce qui freine le bruteforce","Il produit une empreinte plus courte donc plus rapide à comparer","Il est réversible, ce qui permet de récupérer le mot de passe oublié","Il n'a pas besoin de sel car il chiffre déjà le mot de passe"],"answer":0,"explanation":"SHA-256 est conçu pour être RAPIDE : un GPU en calcule des milliards par seconde, idéal pour l'attaquant. bcrypt (comme scrypt, Argon2) est délibérément coûteux et son facteur de travail est réglable pour suivre l'évolution du matériel. bcrypt intègre d'ailleurs un sel et reste à sens unique (non réversible).","tags":["bcrypt","sha-256","mot-de-passe","bruteforce","coût"],"optionNotes":["Exact : bcrypt est lent et à coût réglable, ce qui freine le bruteforce hors ligne.","Non : une empreinte courte et rapide sert justement l'attaquant, pas la sécurité.","Faux : bcrypt est à sens unique ; on ne récupère jamais un mot de passe haché.","Non : bcrypt intègre bien un sel et ne chiffre pas ; il hache."]},
  {"id":"cr-lenteur-volontaire","type":"mcq","domain":"software","topic":"cryptography","difficulty":"intermediate","title":"Lenteur volontaire","company":"Aumasson « Serious Cryptography », chap. 7","question":"Pourquoi les fonctions de hachage de mot de passe (Argon2, scrypt) sont-elles volontairement lentes ?","options":["Pour augmenter le coût d'une attaque par force brute côté attaquant","Parce que le chiffrement asymétrique qu'elles utilisent est lent","Pour laisser le temps au serveur de vérifier le certificat TLS","Parce qu'elles régénèrent une paire de clés à chaque appel"],"answer":0,"explanation":"Un léger surcoût (quelques dizaines de ms) est négligeable pour un login légitime mais rend prohibitif un bruteforce de milliards d'essais. scrypt et Argon2 ajoutent un coût MÉMOIRE, ce qui neutralise l'avantage des GPU/ASIC. Ces fonctions n'utilisent ni asymétrique ni génération de clés.","tags":["argon2","scrypt","force-brute","coût","mot-de-passe"],"optionNotes":["Exact : le surcoût par essai rend un bruteforce de milliards d'essais prohibitif.","Non : Argon2/scrypt n'utilisent pas d'asymétrique ; ils sont symétriques et lents.","Faux : ces fonctions n'ont aucun lien avec la vérification du certificat TLS.","Non : elles ne génèrent aucune paire de clés à chaque appel."]},
  {"id":"cr-cbc-contre-ctr","type":"mcq","domain":"software","topic":"cryptography","difficulty":"intermediate","title":"CBC contre CTR","company":"Aumasson « Serious Cryptography », chap. 4","question":"Quelle différence essentielle distingue le mode CBC du mode CTR ?","options":["CTR transforme le chiffrement par bloc en chiffrement par flot","CBC ne nécessite aucun IV alors que CTR en exige un","CTR chiffre chaque bloc indépendamment sans aucune valeur variable","CBC authentifie automatiquement les données, contrairement à CTR"],"answer":0,"explanation":"CTR chiffre un compteur (nonce||compteur) pour produire un flux XORé au clair : le chiffrement par bloc devient un chiffrement par FLOT, parallélisable et sans padding. CBC enchaîne les blocs (chaque bloc dépend du précédent) et exige un padding. Les DEUX ont besoin d'un IV/nonce, et AUCUN des deux n'authentifie (d'où l'intérêt de GCM).","tags":["cbc","ctr","mode","flot","aes"],"optionNotes":["Exact : CTR chiffre un compteur et XOR le clair, transformant le bloc en flot.","Faux : CBC aussi exige un IV ; les deux en ont besoin.","Non : CTR utilise bien une valeur variable (nonce||compteur), pas rien.","Faux : CBC n'authentifie pas ; c'est GCM qui ajoute l'authentification."]},
  {"id":"cr-apport-de-gcm-sur-ctr","type":"mcq","domain":"software","topic":"cryptography","difficulty":"intermediate","title":"Apport de GCM sur CTR","company":"Wong « Real-World Cryptography », chap. 4 ; Aumasson chap. 8","question":"Que fournit le mode AES-GCM par rapport au mode AES-CTR seul ?","options":["Une authentification intégrée via un tag qui détecte toute altération","Un chiffrement plus court qui réduit la taille du message final","La possibilité de se passer complètement de nonce ou d'IV","Un déchiffrement possible sans connaître la clé symétrique"],"answer":0,"explanation":"GCM = CTR (pour la confidentialité) + GHASH (pour produire un tag d'authentification). Ce tag garantit l'intégrité et l'authenticité : tout octet modifié fait échouer la vérification. CTR seul chiffre mais laisse le message malléable. GCM a toujours besoin d'un nonce et ajoute même 16 octets de tag.","tags":["gcm","ctr","aead","tag","authentification"],"optionNotes":["Exact : GCM ajoute un tag (GHASH) qui détecte toute altération du chiffré.","Non : GCM n'est pas plus court ; il ajoute même 16 octets de tag.","Faux : GCM a toujours besoin d'un nonce, comme CTR.","Non : sans la clé on ne déchiffre pas ; le tag n'y change rien."]},
  {"id":"cr-ecc-face-a-rsa","type":"mcq","domain":"software","topic":"cryptography","difficulty":"intermediate","title":"ECC face à RSA","company":"Aumasson « Serious Cryptography », chap. 12 (Elliptic Curves)","question":"Pourquoi l'ECC est-il souvent préféré à RSA à sécurité équivalente ?","options":["Une clé ECC de 256 bits équivaut en sécurité à RSA 3072 bits","L'ECC est un algorithme symétrique donc plus rapide que RSA","L'ECC ne nécessite pas de clé privée, seulement une clé publique","L'ECC permet de chiffrer sans aucune opération mathématique coûteuse"],"answer":0,"explanation":"Le problème du logarithme discret sur courbes elliptiques est bien plus dur que la factorisation à taille égale : ~256 bits d'ECC offrent la sécurité de ~3072 bits de RSA. Des clés plus courtes donnent des signatures/handshakes plus rapides et moins de bande passante. L'ECC reste de l'asymétrique (paire de clés publique/privée).","tags":["ecc","rsa","taille-clé","courbes-elliptiques","sécurité"],"optionNotes":["Exact : ~256 bits d'ECC équivalent à ~3072 bits de RSA, d'où des clés bien plus courtes.","Non : l'ECC reste asymétrique (paire de clés), pas symétrique.","Faux : l'ECC a bien une clé privée ; c'est de l'asymétrique.","Non : l'ECC repose sur des maths coûteuses (log discret sur courbe)."]},
  {"id":"cr-ecdh-et-diffie-hellman","type":"mcq","domain":"software","topic":"cryptography","difficulty":"intermediate","title":"ECDH et Diffie-Hellman","company":"Wong « Real-World Cryptography », chap. 5","question":"Qu'est-ce que l'ECDH par rapport au Diffie-Hellman classique ?","options":["Un Diffie-Hellman opérant sur des courbes elliptiques, plus efficace","Un échange de clés utilisant RSA au lieu du logarithme discret","Un protocole qui échange la clé secrète directement en clair","Une signature numérique dérivée du protocole Diffie-Hellman"],"answer":0,"explanation":"ECDH est Diffie-Hellman transposé sur le groupe des points d'une courbe elliptique. Même principe (secret commun sans le transmettre), mais clés plus courtes et calculs plus rapides. Comme DH, il n'échange jamais le secret en clair et n'est pas une signature (l'équivalent signature étant ECDSA/EdDSA).","tags":["ecdh","diffie-hellman","courbes-elliptiques","échange-clés"],"optionNotes":["Exact : ECDH est DH sur courbes elliptiques : clés plus courtes, calculs plus rapides.","Non : ECDH repose sur le log discret elliptique, pas sur RSA.","Faux : comme DH, ECDH n'échange jamais le secret en clair.","Non : l'équivalent signature est ECDSA/EdDSA, pas ECDH."]},
  {"id":"cr-confidentialite-persistante","type":"mcq","domain":"software","topic":"cryptography","difficulty":"intermediate","title":"Confidentialité persistante","company":"Wong « Real-World Cryptography », chap. 9 ; TLS 1.3","question":"Que garantit la confidentialité persistante (forward secrecy) ?","options":["La fuite future de la clé long terme ne révèle pas les sessions passées","Les messages restent chiffrés même si l'utilisateur perd son mot de passe","La clé de session reste identique pendant toute la durée de la connexion","Le serveur peut déchiffrer d'anciennes sessions en cas d'audit légal"],"answer":0,"explanation":"La forward secrecy s'obtient avec des échanges éphémères (DHE/ECDHE) : chaque session utilise une clé jetable, indépendante de la clé long terme du serveur. Ainsi, un attaquant qui enregistre le trafic puis vole plus tard la clé privée du serveur ne pourra PAS déchiffrer les sessions passées. C'est l'inverse d'une clé de session figée.","tags":["forward-secrecy","éphémère","dhe","ecdhe","session"],"optionNotes":["Exact : avec des clés éphémères (ECDHE), voler la clé long terme ne livre pas le passé.","Non : la forward secrecy concerne la clé long terme du serveur, pas un mot de passe.","Faux : une clé de session figée est justement le contraire de la forward secrecy.","Non : la forward secrecy vise précisément à empêcher ce déchiffrement a posteriori."]},
  {"id":"cr-validation-d-un-certificat","type":"mcq","domain":"software","topic":"cryptography","difficulty":"intermediate","title":"Validation d'un certificat","company":"Wong « Real-World Cryptography », chap. 9 (PKI)","question":"Comment un navigateur valide-t-il le certificat d'un site web ?","options":["Il vérifie la chaîne de signatures jusqu'à une autorité racine de confiance","Il compare le certificat à une copie stockée localement sur le disque","Il demande le mot de passe du serveur pour confirmer son identité","Il déchiffre le certificat avec la clé privée du serveur distant"],"answer":0,"explanation":"Le navigateur remonte la chaîne : le certificat du site est signé par un intermédiaire, lui-même signé jusqu'à une CA racine présente dans le magasin de confiance du système. Il vérifie aussi le nom de domaine, la date de validité et le statut de révocation. Aucun mot de passe ni clé privée du serveur n'entre en jeu.","tags":["certificat","chaîne","autorité-racine","pki","validation"],"optionNotes":["Exact : le navigateur remonte la chaîne jusqu'à une CA racine de confiance.","Non : il ne compare pas à une copie locale ; il vérifie une signature.","Faux : aucun mot de passe du serveur n'intervient dans la validation.","Non : il vérifie une signature avec la clé publique, il ne déchiffre rien."]},
  {"id":"cr-objectif-du-handshake-tls","type":"mcq","domain":"software","topic":"cryptography","difficulty":"intermediate","title":"Objectif du handshake TLS","company":"Wong « Real-World Cryptography », chap. 9 ; Aumasson chap. 13","question":"Quel est l'objectif principal du handshake TLS ?","options":["Authentifier le serveur et négocier des clés de session partagées","Compresser les données de l'application avant de les transmettre","Stocker le mot de passe de l'utilisateur de façon sécurisée","Remplacer le protocole TCP pour accélérer les connexions"],"answer":0,"explanation":"Le handshake TLS authentifie le serveur (via son certificat), négocie les algorithmes (cipher suite) et établit, par un échange de clés (ECDHE), des clés symétriques de session. Ensuite, les données applicatives sont chiffrées avec un AEAD. TLS fonctionne AU-DESSUS de TCP et ne le remplace pas.","tags":["tls","handshake","authentification","session","négociation"],"optionNotes":["Exact : le handshake authentifie le serveur et négocie les clés de session.","Non : TLS ne compresse pas les données (retiré car dangereux, cf. CRIME).","Faux : TLS ne stocke pas de mot de passe ; il sécurise le transport.","Non : TLS fonctionne AU-DESSUS de TCP, il ne le remplace pas."]},
  {"id":"cr-hmac-plutot-que-hash-cle-message","type":"mcq","domain":"software","topic":"cryptography","difficulty":"intermediate","title":"HMAC plutôt que hash(clé||message)","company":"Aumasson « Serious Cryptography », chap. 7","question":"Pourquoi utiliser HMAC(clé, message) plutôt que hash(clé || message) ?","options":["HMAC résiste aux attaques par extension de longueur, contrairement au second","HMAC est plus rapide car il n'appelle la fonction de hachage qu'une fois","HMAC produit une empreinte réversible que l'on peut déchiffrer","HMAC ne nécessite aucune clé secrète pour être calculé"],"answer":0,"explanation":"Avec une fonction Merkle-Damgård (MD5, SHA-1, SHA-256), hash(clé||message) est vulnérable à l'extension de longueur : un attaquant peut ajouter des données et produire un MAC valide sans connaître la clé. La construction imbriquée de HMAC (hash imbriqué avec ipad/opad) neutralise cette attaque. HMAC reste à sens unique et utilise bien une clé.","tags":["hmac","extension-longueur","mac","sha-2","clé"],"optionNotes":["Exact : HMAC neutralise l'extension de longueur qui frappe hash(clé||message).","Non : HMAC appelle le hachage deux fois (imbriqué), il n'est pas plus rapide.","Faux : HMAC reste à sens unique ; on ne déchiffre pas un MAC.","Non : HMAC utilise bien une clé secrète, c'est tout son intérêt."]},
  {"id":"cr-sha-3-face-a-sha-2","type":"mcq","domain":"software","topic":"cryptography","difficulty":"intermediate","title":"SHA-3 face à SHA-2","company":"Aumasson « Serious Cryptography », chap. 6","question":"Quelle différence structurelle sépare SHA-3 de SHA-2 ?","options":["SHA-3 repose sur une construction en éponge, pas sur Merkle-Damgård","SHA-3 est un algorithme de chiffrement alors que SHA-2 hache","SHA-3 produit toujours une empreinte plus courte que SHA-2","SHA-3 nécessite une clé secrète alors que SHA-2 n'en a pas besoin"],"answer":0,"explanation":"SHA-3 (Keccak) utilise une construction en ÉPONGE (phases d'absorption puis d'essorage), radicalement différente du schéma Merkle-Damgård de SHA-2. Conséquence pratique : SHA-3 n'est PAS vulnérable à l'extension de longueur. Les deux sont des fonctions de hachage sans clé, offrant des tailles d'empreinte comparables (224 à 512 bits).","tags":["sha-3","sha-2","éponge","keccak","merkle-damgard"],"optionNotes":["Exact : SHA-3 (Keccak) est une éponge, immune à l'extension de longueur.","Non : SHA-3 hache aussi ; ce n'est pas un algorithme de chiffrement.","Faux : SHA-3 offre des tailles comparables (224 à 512 bits).","Non : SHA-3 n'a pas de clé, comme SHA-2 ; HMAC en ajouterait une."]},
  {"id":"cr-variante-d-argon2","type":"mcq","domain":"software","topic":"cryptography","difficulty":"intermediate","title":"Variante d'Argon2","company":"RFC 9106 (Argon2) ; OWASP Password Storage Cheat Sheet","question":"Quelle variante d'Argon2 est recommandée pour le hachage de mots de passe généraliste ?","options":["Argon2id, qui combine résistance au side-channel et au GPU","Argon2d seul, optimisé uniquement contre les attaques temporelles","Argon2i seul, le plus rapide au détriment de la sécurité mémoire","Argon2s, la variante conçue spécifiquement pour les cartes à puce"],"answer":0,"explanation":"La RFC 9106 recommande Argon2id par défaut : il mélange Argon2i (accès mémoire indépendants des données, résistant aux attaques par canal auxiliaire) et Argon2d (accès dépendants des données, résistant aux GPU/TMTO). Argon2d seul est sensible aux side-channels, Argon2i seul un peu plus faible face au GPU, et « Argon2s » n'existe pas.","tags":["argon2","argon2id","mot-de-passe","mémoire","gpu"],"optionNotes":["Exact : la RFC 9106 recommande Argon2id, hybride résistant side-channel et GPU.","Non : Argon2d seul est sensible aux attaques par canal auxiliaire.","Faux : Argon2i seul est un peu plus faible face aux attaques GPU/TMTO.","Non : « Argon2s » n'existe pas ; les variantes sont d, i et id."]},
  {"id":"cr-comparaison-de-jeton","type":"find-error","domain":"software","topic":"cryptography","difficulty":"intermediate","title":"Comparaison de jeton","company":"Aumasson « Serious Cryptography », chap. 7 ; Wong chap. 3","language":"python","code":"import hashlib\n\ndef verify_token(user_token: str, stored_token: str) -> bool:\n    # Compare le jeton fourni au jeton attendu\n    if user_token == stored_token:\n        return True\n    return False","question":"Quelle vulnérabilité affecte cette vérification de jeton ?","options":["La comparaison == n'est pas à temps constant et fuit via une attaque temporelle","Le jeton devrait être haché avec MD5 avant d'être comparé","La fonction devrait renvoyer une chaîne plutôt qu'un booléen","L'import de hashlib est inutile et ralentit l'exécution du script"],"answer":0,"explanation":"L'opérateur == s'arrête au premier octet qui diffère : le temps de réponse dépend du nombre d'octets corrects en tête. En mesurant ces micro-écarts, un attaquant peut reconstruire le jeton octet par octet. Il faut une comparaison à temps constant : hmac.compare_digest(user_token, stored_token) en Python.","tags":["timing","comparaison","temps-constant","jeton","compare_digest"],"optionNotes":["Exact : == s'arrête au premier octet différent ; utiliser hmac.compare_digest.","Non : hacher en MD5 n'aide pas et MD5 est cassé ; le souci est le timing.","Faux : renvoyer un booléen convient ; ce n'est pas le problème.","Non : l'import n'est pas le sujet ; la faille est la comparaison non constante."]},
  {"id":"cr-chiffrement-aes-en-ecb","type":"find-error","domain":"software","topic":"cryptography","difficulty":"intermediate","title":"Chiffrement AES en ECB","company":"Aumasson « Serious Cryptography », chap. 4","language":"python","code":"from Crypto.Cipher import AES\n\ndef encrypt(data: bytes, key: bytes) -> bytes:\n    cipher = AES.new(key, AES.MODE_ECB)\n    padded = data + b\"\\x00\" * (16 - len(data) % 16)\n    return cipher.encrypt(padded)","question":"Quel est le principal défaut cryptographique de ce code ?","options":["Le mode ECB révèle les motifs : deux blocs identiques donnent le même chiffré","La clé AES doit obligatoirement faire 512 bits pour être sûre","AES ne peut chiffrer que du texte ASCII, pas des octets bruts","Le padding par zéros accélère trop le chiffrement des données"],"answer":0,"explanation":"Le vrai problème est MODE_ECB : sans IV, chaque bloc est chiffré indépendamment, donc les répétitions du clair transparaissent dans le chiffré (fuite de structure). Il faut un mode authentifié comme GCM avec un nonce unique. Accessoirement, le padding par zéros est ambigu (impossible de distinguer un vrai \\x00 final) : préférer PKCS#7.","tags":["ecb","aes","motif","mode","chiffrement"],"optionNotes":["Exact : ECB sans IV laisse transparaître les motifs du clair ; préférer GCM.","Faux : AES-256 a des clés de 256 bits, jamais 512.","Non : AES chiffre des octets bruts, pas seulement de l'ASCII.","Faux : le padding par zéros est ambigu, pas trop rapide ; préférer PKCS#7."]},
  {"id":"cr-cle-secrete-en-dur","type":"find-error","domain":"software","topic":"cryptography","difficulty":"senior","title":"Clé secrète en dur","company":"Ferguson/Schneier/Kohno « Cryptography Engineering » (key management) ; OWASP","language":"python","code":"from cryptography.fernet import Fernet\n\nSECRET_KEY = b\"gAAAAABk9mVQ7Xn2zR4tYb8wKp1LcVfE3sQ=\"\n\ndef encrypt_message(msg: str) -> bytes:\n    f = Fernet(SECRET_KEY)\n    return f.encrypt(msg.encode())","question":"Quel problème de sécurité majeur ce code présente-t-il ?","options":["La clé secrète est codée en dur dans le source et donc exposée","Fernet est un algorithme obsolète qu'il ne faut plus utiliser","Le message devrait être haché avant d'être chiffré avec Fernet","La fonction devrait renvoyer une chaîne au lieu d'octets"],"answer":0,"explanation":"Une clé en dur finit dans le dépôt Git, les images Docker, les sauvegardes et les logs : elle est compromise dès qu'une seule copie du code fuit, et impossible à faire tourner sans redéployer. La clé doit venir d'un secret manager, d'une variable d'environnement ou d'un HSM, séparée du code. Fernet lui-même (AES-CBC + HMAC) est parfaitement valide.","tags":["clé-en-dur","gestion-clés","secret","source","exposition"],"optionNotes":["Exact : une clé en dur fuit via Git, images et logs, et ne tourne pas sans redéploi.","Non : Fernet (AES-CBC + HMAC) est parfaitement valide ; le souci est la clé en dur.","Faux : hacher avant de chiffrer n'a pas de sens ici.","Non : renvoyer des octets convient ; ce n'est pas le problème de sécurité."]},
  {"id":"cr-iv-fixe-en-cbc","type":"find-error","domain":"software","topic":"cryptography","difficulty":"senior","title":"IV fixe en CBC","company":"Aumasson « Serious Cryptography », chap. 4 ; Wong chap. 4","language":"python","code":"from Crypto.Cipher import AES\n\nIV = b\"0000000000000000\"\n\ndef encrypt(data: bytes, key: bytes) -> bytes:\n    cipher = AES.new(key, AES.MODE_CBC, IV)\n    return cipher.encrypt(pad(data))","question":"Quelle erreur cryptographique contient ce code ?","options":["L'IV est fixe : deux messages identiques produisent le même chiffré en CBC","L'IV devrait faire 32 octets pour correspondre à la clé AES-256","Le mode CBC est incompatible avec un IV et devrait être retiré","L'IV doit rester secret et ne jamais être transmis avec le message"],"answer":0,"explanation":"En CBC, l'IV doit être ALÉATOIRE et imprévisible, et unique à chaque message. Un IV constant fait que deux clairs identiques (ou partageant un préfixe) produisent des chiffrés identiques, révélant de l'information. L'IV n'est pas secret : on le génère avec un CSPRNG et on le transmet en clair avec le chiffré. Sa taille correcte est un bloc (16 octets).","tags":["iv","cbc","statique","aléa","chiffrement"],"optionNotes":["Exact : en CBC l'IV doit être aléatoire et unique ; fixe, il révèle les répétitions.","Faux : l'IV fait un bloc (16 octets), pas 32 ; il ne suit pas la taille de clé.","Non : CBC exige justement un IV ; il n'est pas incompatible.","Faux : l'IV n'est pas secret ; on le transmet en clair avec le chiffré."]},
  {"id":"cr-encrypt-then-mac","type":"mcq","domain":"software","topic":"cryptography","difficulty":"senior","title":"Encrypt-then-MAC","company":"Wong « Real-World Cryptography », chap. 4 ; Aumasson chap. 8","question":"Pourquoi l'ordre « Encrypt-then-MAC » est-il préféré à « MAC-then-Encrypt » ?","options":["Il permet de rejeter un chiffré altéré sans jamais le déchiffrer","Il produit un message final plus court à transmettre sur le réseau","Il évite d'avoir à utiliser une clé pour calculer le MAC","Il chiffre le MAC, ce qui le rend impossible à recalculer"],"answer":0,"explanation":"Avec Encrypt-then-MAC, on vérifie d'abord le tag sur le chiffré : s'il est invalide, on rejette AVANT tout déchiffrement, ce qui coupe court aux oracles de padding (type Vaudenay/Lucky13 qui ont frappé MAC-then-Encrypt dans TLS). C'est l'ordre prouvé sûr et utilisé par les AEAD modernes. Les deux ordres utilisent une clé de MAC.","tags":["encrypt-then-mac","aead","intégrité","ordre","oracle"],"optionNotes":["Exact : on vérifie le tag avant tout déchiffrement, coupant les oracles de padding.","Non : l'ordre ne raccourcit pas le message ; il concerne la sécurité.","Faux : les deux ordres utilisent bien une clé de MAC.","Non : le MAC n'a pas à être secret ; le vérifier d'abord est le vrai gain."]},
  {"id":"cr-jeton-avec-random","type":"find-error","domain":"software","topic":"cryptography","difficulty":"senior","title":"Jeton avec random","company":"Aumasson « Serious Cryptography », chap. 2 ; documentation Python `secrets`","language":"python","code":"import random\n\ndef generate_reset_token() -> str:\n    return \"\".join(random.choice(\"0123456789abcdef\") for _ in range(32))","question":"Pourquoi ce générateur de jeton de réinitialisation est-il dangereux ?","options":["Le module random n'est pas cryptographique et ses sorties sont prévisibles","Le jeton de 32 caractères est bien trop long pour être stocké","L'alphabet hexadécimal empêche toute unicité entre deux jetons","La fonction devrait renvoyer des octets plutôt qu'une chaîne de caractères"],"answer":0,"explanation":"random s'appuie sur Mersenne Twister : en observant assez de sorties, on reconstitue l'état interne et on PRÉDIT les jetons suivants, permettant de détourner la réinitialisation d'un autre compte. Il faut un CSPRNG : secrets.token_hex(16) ou secrets.token_urlsafe(). La règle vaut pour tout secret (jetons, clés, nonces imprévisibles).","tags":["prng","csprng","jeton","secrets","imprévisibilité"],"optionNotes":["Exact : random (Mersenne Twister) est prévisible ; utiliser secrets.token_hex.","Non : 32 caractères n'est pas trop long ; le souci est la prévisibilité.","Faux : l'hexadécimal n'empêche pas l'unicité ; la faille est le PRNG.","Non : renvoyer une chaîne convient ; c'est la source d'aléa qui est fautive."]},
  {"id":"cr-piege-des-72-octets-de-bcrypt","type":"mcq","domain":"software","topic":"cryptography","difficulty":"senior","title":"Piège des 72 octets de bcrypt","company":"Aumasson « Serious Cryptography », chap. 7 ; OWASP Password Storage","question":"Quel piège spécifique faut-il connaître avec bcrypt ?","options":["Il tronque silencieusement le mot de passe au-delà de 72 octets","Il ne fonctionne qu'avec des mots de passe strictement en ASCII","Il exige un sel fourni manuellement par le développeur à chaque appel","Il stocke le mot de passe en clair dans les 22 premiers caractères"],"answer":0,"explanation":"bcrypt n'utilise que les 72 premiers OCTETS de l'entrée et ignore le reste sans erreur : deux mots de passe partageant ce préfixe deviennent équivalents (problématique avec des phrases longues ou des caractères multi-octets). Une parade courante est de pré-hacher (SHA-256) puis d'encoder avant bcrypt, ou d'utiliser Argon2. bcrypt gère lui-même son sel.","tags":["bcrypt","troncature","72-octets","mot-de-passe","piège"],"optionNotes":["Exact : bcrypt ignore silencieusement tout octet au-delà du 72e.","Non : bcrypt accepte des octets non-ASCII (attention au comptage en octets).","Faux : bcrypt gère lui-même son sel, pas besoin de le fournir.","Non : bcrypt ne stocke jamais le mot de passe en clair."]},
  {"id":"cr-reutilisation-de-nonce-en-gcm","type":"mcq","domain":"software","topic":"cryptography","difficulty":"senior","title":"Réutilisation de nonce en GCM","company":"Aumasson « Serious Cryptography », chap. 8 ; attaque « forbidden » de Joux","question":"En AES-GCM, pourquoi ne doit-on JAMAIS réutiliser un nonce avec la même clé ?","options":["Cela compromet la confidentialité et permet de forger des tags valides","Cela allonge inutilement le temps de chiffrement des messages","Cela empêche le destinataire de retrouver le bon nonce pour déchiffrer","Cela rend le tag d'authentification deux fois plus long que prévu"],"answer":0,"explanation":"GCM chiffre en CTR : réutiliser un nonce révèle le XOR des clairs (perte de confidentialité). Pire, cela expose la clé d'authentification H (l'attaque « forbidden » de Joux), permettant de FORGER des messages avec un tag valide. GCM tolère très peu de nonces avant risque : au-delà, préférer XChaCha20-Poly1305 ou AES-GCM-SIV.","tags":["gcm","nonce","réutilisation","forge","tag"],"optionNotes":["Exact : réutiliser un nonce révèle le XOR des clairs et expose H (forge de tags).","Non : cela ne change pas le temps de chiffrement ; c'est un désastre de sécurité.","Faux : le nonce est transmis, le destinataire n'a pas à le retrouver.","Non : le tag garde sa taille (16 octets) ; le vrai risque est la forge."]},
  {"id":"cr-rsa-oaep-contre-pkcs-1-v1-5","type":"mcq","domain":"software","topic":"cryptography","difficulty":"senior","title":"RSA-OAEP contre PKCS#1 v1.5","company":"Aumasson « Serious Cryptography », chap. 10 (RSA) ; Wong chap. 6","question":"Pourquoi préférer OAEP à PKCS#1 v1.5 pour le chiffrement RSA ?","options":["PKCS#1 v1.5 est vulnérable à l'oracle de padding (Bleichenbacher)","OAEP produit un chiffré plus court, donc plus rapide à transmettre","PKCS#1 v1.5 nécessite une clé privée pour chiffrer, pas OAEP","OAEP permet de se passer complètement de génération d'aléa"],"answer":0,"explanation":"Le padding PKCS#1 v1.5 pour le chiffrement se prête à l'attaque de Bleichenbacher : un serveur qui distingue un padding valide d'un invalide devient un oracle permettant de déchiffrer sans la clé (attaques ROBOT réactualisées). OAEP, prouvé sûr, ajoute une structure aléatoire robuste. Les deux chiffrent avec la clé publique et OAEP a besoin d'aléa.","tags":["rsa","oaep","pkcs1","bleichenbacher","padding"],"optionNotes":["Exact : PKCS#1 v1.5 se prête à l'oracle de padding de Bleichenbacher (ROBOT).","Non : OAEP n'est pas plus court ; il ajoute une structure de padding.","Faux : les deux chiffrent avec la clé PUBLIQUE, pas la privée.","Non : OAEP a besoin d'aléa (MGF) ; il ne s'en passe pas."]},
  {"id":"cr-nonce-reutilise-en-ecdsa","type":"mcq","domain":"software","topic":"cryptography","difficulty":"senior","title":"Nonce réutilisé en ECDSA","company":"Aumasson « Serious Cryptography », chap. 12 ; incident PlayStation 3","question":"Que se passe-t-il si deux signatures ECDSA réutilisent le même nonce k ?","options":["La clé privée du signataire peut être entièrement récupérée par calcul","Les deux signatures deviennent identiques mais restent parfaitement sûres","Le vérificateur ne pourra plus valider aucune des deux signatures","La clé publique change et doit être régénérée par le signataire"],"answer":0,"explanation":"En ECDSA/DSA, le nonce k doit être unique et secret par signature. Deux signatures avec le même k sur des messages différents donnent un système linéaire dont on extrait k, puis la clé privée d. C'est ainsi que la clé de la PS3 fut extraite (k constant) et que des portefeuilles Bitcoin ont été vidés. EdDSA évite le risque en dérivant k de façon déterministe.","tags":["ecdsa","nonce","k","clé-privée","signature"],"optionNotes":["Exact : deux signatures au même k donnent un système linéaire livrant la clé privée.","Non : loin d'être sûr, cela révèle la clé privée (cf. PS3).","Faux : les signatures restent vérifiables ; c'est la clé qui fuit.","Non : la clé publique ne change pas ; c'est la privée qui est compromise."]},
  {"id":"cr-cle-api-avec-math-random","type":"find-error","domain":"software","topic":"cryptography","difficulty":"senior","title":"Clé API avec Math.random","company":"Wong « Real-World Cryptography », chap. 8 ; MDN Web Crypto API","language":"javascript","code":"function generateApiKey() {\n  let key = \"\";\n  for (let i = 0; i < 32; i++) {\n    key += Math.floor(Math.random() * 16).toString(16);\n  }\n  return key;\n}","question":"Quel est le défaut de sécurité de ce générateur de clé API ?","options":["Math.random n'est pas cryptographiquement sûr et reste prédictible","La boucle de 32 itérations est trop courte pour produire une clé","toString(16) tronque la clé et supprime des caractères importants","La clé devrait être générée côté client plutôt que côté serveur"],"answer":0,"explanation":"Math.random n'offre aucune garantie cryptographique : son état interne peut être reconstruit, rendant les clés futures prédictibles. Il faut un CSPRNG : crypto.getRandomValues(new Uint8Array(16)) dans le navigateur, ou crypto.randomBytes(16) sous Node.js. La longueur n'est pas le problème ; générer un secret côté client serait au contraire une faute.","tags":["math-random","csprng","javascript","clé-api","imprévisibilité"],"optionNotes":["Exact : Math.random n'est pas sûr ; utiliser crypto.getRandomValues/randomBytes.","Non : 32 itérations suffisent ; le souci est la prévisibilité, pas la longueur.","Faux : toString(16) ne tronque rien d'important ici.","Non : générer un secret côté client serait au contraire une faute."]},
  {"id":"cr-controle-d-integrite-md5","type":"find-error","domain":"software","topic":"cryptography","difficulty":"senior","title":"Contrôle d'intégrité MD5","company":"Aumasson « Serious Cryptography », chap. 6 ; collisions MD5 (Wang, Flame)","language":"python","code":"import hashlib\n\ndef file_fingerprint(data: bytes) -> str:\n    return hashlib.md5(data).hexdigest()\n\ndef verify_download(data: bytes, expected: str) -> bool:\n    return file_fingerprint(data) == expected","question":"Pourquoi ce contrôle d'intégrité est-il non fiable pour un usage sécurité ?","options":["MD5 est cassé : on sait forger deux contenus ayant la même empreinte","hexdigest tronque l'empreinte MD5 à la moitié de sa taille réelle","MD5 nécessite une clé secrète absente ici pour être calculé","La comparaison devrait porter sur les octets bruts, pas l'hexadécimal"],"answer":0,"explanation":"MD5 n'a plus aucune résistance aux collisions : on génère à volonté deux fichiers de même empreinte (le malware Flame l'a exploité pour forger un certificat). Un attaquant peut donc substituer un fichier malveillant sans changer l'empreinte. Il faut SHA-256 pour l'intégrité, et un HMAC ou une signature si la source doit aussi être authentifiée.","tags":["md5","collision","intégrité","obsolète","hachage"],"optionNotes":["Exact : MD5 permet de forger deux contenus de même empreinte (cf. Flame).","Non : hexdigest ne tronque rien ; MD5 fait bien 128 bits.","Faux : MD5 n'a pas de clé ; le vrai défaut est l'absence de résistance aux collisions.","Non : comparer en hexa ou en octets ne change rien ; MD5 est le problème."]},
  {"id":"cr-attaque-par-extension-de-longueur","type":"mcq","domain":"software","topic":"cryptography","difficulty":"senior","title":"Attaque par extension de longueur","company":"Aumasson « Serious Cryptography », chap. 6-7","question":"Qu'est-ce qu'une attaque par extension de longueur sur SHA-256 ?","options":["Ajouter des données à un message et recalculer un MAC valide sans la clé","Retrouver la clé secrète en observant le temps de calcul du hachage","Provoquer une collision en allongeant indéfiniment le message d'entrée","Déchiffrer une empreinte en essayant toutes les longueurs possibles"],"answer":0,"explanation":"Les fonctions Merkle-Damgård (MD5, SHA-1, SHA-256) exposent leur état interne dans l'empreinte finale. Connaissant H(clé||message) et la longueur, un attaquant reprend cet état et calcule H(clé||message||padding||ajout) sans connaître la clé, forgeant un MAC valide. La parade : HMAC, ou SHA-3/BLAKE2 (immunes par construction).","tags":["extension-longueur","merkle-damgard","sha-256","hmac","mac"],"optionNotes":["Exact : depuis H(clé||message) on prolonge et forge un MAC valide sans la clé.","Non : retrouver la clé par le timing est une autre attaque (canal auxiliaire).","Faux : ce n'est pas une collision ; on étend le message, on n'en cherche pas deux.","Non : on ne déchiffre pas une empreinte ; le hachage est à sens unique."]},
  {"id":"cr-nouveautes-de-tls-1-3","type":"mcq","domain":"software","topic":"cryptography","difficulty":"senior","title":"Nouveautés de TLS 1.3","company":"Wong « Real-World Cryptography », chap. 9 ; RFC 8446","question":"Quel changement majeur TLS 1.3 apporte-t-il par rapport à TLS 1.2 ?","options":["L'échange de clés RSA statique est supprimé au profit d'(EC)DHE éphémère","Le chiffrement symétrique est abandonné au profit du seul RSA","Les certificats ne sont plus nécessaires pour authentifier le serveur","Le handshake se fait désormais entièrement en clair sans chiffrement"],"answer":0,"explanation":"TLS 1.3 impose la forward secrecy : l'ancien échange où le client chiffrait le secret avec la clé RSA du serveur (sans forward secrecy) est retiré, seul (EC)DHE éphémère subsiste. Le protocole abandonne aussi RC4, CBC, la compression, réduit le handshake à 1-RTT (voire 0-RTT) et n'autorise que des AEAD. Les certificats restent indispensables.","tags":["tls-1.3","forward-secrecy","ecdhe","rsa","handshake"],"optionNotes":["Exact : TLS 1.3 retire l'échange RSA statique, ne gardant qu'(EC)DHE éphémère.","Faux : le symétrique reste central (AEAD) ; RSA seul ne chiffre pas les données.","Non : les certificats restent indispensables pour authentifier le serveur.","Faux : le handshake 1.3 chiffre au contraire une grande partie de ses messages."]},
  {"id":"cr-bonne-gestion-des-cles","type":"mcq","domain":"software","topic":"cryptography","difficulty":"senior","title":"Bonne gestion des clés","company":"Ferguson/Schneier/Kohno « Cryptography Engineering » (key management)","question":"Quelle est une bonne pratique de gestion des clés cryptographiques ?","options":["Stocker les clés dans un secret manager ou HSM, séparé du code source","Inclure les clés dans le dépôt Git pour faciliter le déploiement","Réutiliser la même clé pour tous les usages afin de simplifier","Envoyer la clé privée au client pour qu'il vérifie les signatures"],"answer":0,"explanation":"Les clés doivent vivre hors du code, dans un secret manager (Vault, KMS) ou un HSM, avec accès restreint, rotation planifiée et séparation des usages (une clé = un rôle). Les mettre dans Git, en réutiliser une pour tout, ou diffuser une clé PRIVÉE (on ne partage jamais que la publique) sont des fautes classiques qui compromettent tout le système.","tags":["gestion-clés","hsm","secret-manager","rotation","séparation"],"optionNotes":["Exact : clés hors du code, dans un secret manager/HSM, avec rotation et accès restreint.","Non : mettre des clés dans Git les compromet dès la moindre fuite du dépôt.","Faux : une clé = un usage ; tout réutiliser propage une compromission.","Non : on ne diffuse jamais la clé privée ; la vérification se fait avec la publique."]},
  {"id":"cr-nonce-gcm-partage","type":"find-error","domain":"software","topic":"cryptography","difficulty":"senior","title":"Nonce GCM partagé","company":"Aumasson « Serious Cryptography », chap. 8","language":"python","code":"from Crypto.Cipher import AES\n\ndef encrypt_all(messages, key):\n    nonce = b\"fixed_nonce_\"  # 12 octets reutilises\n    out = []\n    for m in messages:\n        cipher = AES.new(key, AES.MODE_GCM, nonce=nonce)\n        ct, tag = cipher.encrypt_and_digest(m)\n        out.append((ct, tag))\n    return out","question":"Quelle faille critique contient cette fonction de chiffrement ?","options":["Le même nonce GCM sert à tous les messages, ce qui casse la sécurité","Le nonce de 12 octets est trop court et doit en faire 16","Le tag d'authentification ne devrait pas être renvoyé à l'appelant","AES-GCM ne supporte pas le chiffrement de plusieurs messages"],"answer":0,"explanation":"Le nonce est constant pour toute la boucle : catastrophique en GCM. La réutilisation du couple (clé, nonce) révèle le XOR des clairs et surtout expose la clé d'authentification H, permettant la forge de messages. Il faut un nonce unique par message : un compteur, ou os.urandom(12). Le nonce de 12 octets est la taille recommandée, et renvoyer le tag est normal.","tags":["gcm","nonce","réutilisation","aes","forge"],"optionNotes":["Exact : un nonce constant en GCM révèle le XOR des clairs et permet la forge.","Non : 12 octets est justement la taille recommandée du nonce GCM.","Faux : renvoyer le tag est normal ; il sert à vérifier l'intégrité.","Non : GCM chiffre plusieurs messages, à condition d'un nonce unique par message."]},
  {"id":"cr-mot-de-passe-chiffre","type":"find-error","domain":"software","topic":"cryptography","difficulty":"senior","title":"Mot de passe chiffré","company":"OWASP Password Storage ; Ferguson/Schneier/Kohno « Cryptography Engineering »","language":"python","code":"from cryptography.fernet import Fernet\n\ndef store_password(pwd: str, f: Fernet) -> bytes:\n    return f.encrypt(pwd.encode())\n\ndef check_password(pwd: str, stored: bytes, f: Fernet) -> bool:\n    return f.decrypt(stored).decode() == pwd","question":"Quel est le défaut de conception de cette gestion de mots de passe ?","options":["Les mots de passe sont chiffrés (réversibles) au lieu d'être hachés","Fernet ne peut pas chiffrer des chaînes de plus de 16 caractères","La comparaison devrait utiliser un hachage MD5 des deux valeurs","La clé Fernet doit être régénérée à chaque vérification de mot de passe"],"answer":0,"explanation":"Chiffrer un mot de passe est réversible : quiconque obtient la clé (fuite, admin malveillant, sauvegarde) récupère TOUS les mots de passe en clair. Un mot de passe ne doit jamais pouvoir être retrouvé : on le HACHE avec une fonction lente et salée (Argon2, bcrypt, scrypt), puis on compare les empreintes. Le serveur n'a pas besoin de connaître le mot de passe original.","tags":["mot-de-passe","hachage","chiffrement-réversible","stockage","bcrypt"],"optionNotes":["Exact : chiffrer est réversible ; qui a la clé lit tous les mots de passe.","Non : Fernet chiffre des chaînes bien plus longues que 16 caractères.","Faux : MD5 est cassé ; il faut hacher avec Argon2/bcrypt, pas chiffrer.","Non : la clé ne se régénère pas à chaque appel ; le défaut est la réversibilité."]},
];
